<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('admin');csrf_check();$id=(int)($_POST['id_kegiatan']??0);$pid=(int)($_POST['id_petugas']??0);$name=trim($_POST['nama_petugas']??'');$kc=strtoupper(trim($_POST['kecamatan']??''));if(!$name||!in_array($kc,kecamatan_list(),true)){flash('danger','Nama dan kecamatan wajib valid.');redirect('/admin/petugas/index.php?id='.$id);}try{if($pid){$q=$pdo->prepare('UPDATE petugas SET nama_petugas=?,kecamatan=? WHERE id_petugas=? AND id_kegiatan=? AND deleted_at IS NULL');$q->execute([$name,$kc,$pid,$id]);}else{$q=$pdo->prepare('SELECT id_user FROM users WHERE id_kegiatan=? AND role_user=\'petugas\'');$q->execute([$id]);$uid=$q->fetchColumn();if(!$uid)throw new RuntimeException();$s=$pdo->prepare('INSERT INTO petugas(id_kegiatan,id_user,nama_petugas,kecamatan) VALUES(?,?,?,?)');$s->execute([$id,$uid,$name,$kc]);}flash('success','Data petugas berhasil disimpan.');}catch(Throwable $e){flash('danger','Gagal menyimpan. Nama petugas mungkin sudah terdaftar pada kegiatan ini.');}redirect('/admin/petugas/index.php?id='.$id);
